'use client';

import { useLayoutEffect, useRef, type ReactNode } from 'react';
import { cx } from '@/utils/cx';

const layoutProperties = new Set([
  'height', 'block-size', 'min-height', 'max-height', 'min-block-size', 'max-block-size',
  'width', 'inline-size', 'min-width', 'max-width', 'min-inline-size', 'max-inline-size',
  'padding-top', 'padding-bottom', 'padding-left', 'padding-right', 'padding-block-start', 'padding-block-end',
  'margin-top', 'margin-bottom', 'margin-left', 'margin-right', 'margin-block-start', 'margin-block-end',
  'border-top-width', 'border-bottom-width', 'gap', 'row-gap', 'column-gap', 'grid-template-rows', 'grid-template-columns', 'flex-basis', 'font-size', 'line-height', 'letter-spacing',
]);

/** Animate real layout height so adjacent content follows without being scaled. */
export function AnimatedHeight({ children, className }: { children: ReactNode; className?: string }) {
  const frameRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const frame = frameRef.current;
    const content = contentRef.current;
    if (!frame || !content) return;
    // Start at the natural size, including when server-rendered content is nonempty.
    frame.style.transition = 'none';
    frame.style.height = `${content.offsetHeight}px`;
    void frame.offsetHeight;
    frame.style.removeProperty('transition');
    let alive = true;
    const observed = new WeakSet<Animation>();
    const affectsLayout = (animation: Animation) => {
      if (animation.playState !== 'running') return false;
      if ('transitionProperty' in animation) return layoutProperties.has(String(animation.transitionProperty));
      return animation.effect instanceof KeyframeEffect && animation.effect.getKeyframes().some(frame =>
        Object.keys(frame).some(property => layoutProperties.has(property.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`)))
      );
    };
    const nestedLayoutIsMoving = () => content.getAnimations({subtree: true}).some(affectsLayout);
    const restore = () => { if (alive && !nestedLayoutIsMoving()) frame.style.removeProperty('transition'); };
    const observeMotion = () => {
      const moving = content.getAnimations({subtree: true}).filter(affectsLayout);
      for (const animation of moving) if (!observed.has(animation)) {
        observed.add(animation);
        animation.finished.then(restore, restore);
      }
      return moving.length > 0;
    };
    const restoreTransition = (event: TransitionEvent) => {
      if (layoutProperties.has(event.propertyName)) restore();
    };
    content.addEventListener('transitionend', restoreTransition);
    content.addEventListener('transitioncancel', restoreTransition);
    const observer = new ResizeObserver(([entry]) => {
      const height = entry.borderBoxSize?.[0]?.blockSize ?? content.offsetHeight;
      // A child can already be animating its real height. Follow that geometry
      // directly, so nested frames do not each add another full transition.
      const following = observeMotion();
      if (following) frame.style.transition = 'none';
      else frame.style.removeProperty('transition');
      frame.style.height = `${height}px`;
    });
    // Helper text and disclosure spacing can change without changing the
    // content box. Observe the same border box that supplies the target height.
    observer.observe(content, { box: 'border-box' });
    return () => {
      alive = false;
      observer.disconnect();
      content.removeEventListener('transitionend', restoreTransition);
      content.removeEventListener('transitioncancel', restoreTransition);
    };
  }, []);
  return <div ref={frameRef} className={cx('ui-animated-height', className)}><div ref={contentRef} className="ui-animated-height__content">{children}</div></div>;
}

'use client';

import type { ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';
import { Spinner } from '@/components/base/spinner/spinner';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'soft' | 'outline' | 'solid' | 'quiet';
export type ButtonSize = 'medium' | 'small' | 'xs';

type NativeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;
type ContentProps =
  | { iconOnly: true; 'aria-label': string; leadingIcon: IconComponent; children?: never }
  | { iconOnly?: false; children: ReactNode; leadingIcon?: IconComponent };

export type ButtonProps = NativeButtonProps & ContentProps & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  trailingIcon?: IconComponent;
  isLoading?: boolean;
  loadingLabel?: string;
  ref?: Ref<HTMLButtonElement>;
};

const base = 'ui-button inline-flex shrink-0 items-center justify-center whitespace-nowrap select-none outline-none';
const sizes: Record<ButtonSize, string> = {
  medium: 'h-9 rounded-[10px] px-2 gap-0.5',
  small: 'h-8 rounded-lg px-2 gap-0.5',
  xs: 'h-6 rounded-[5px] px-2 gap-0.5',
};
export const buttonIconClassNames: Record<ButtonSize, string> = { medium: 'size-5', small: 'size-[18px]', xs: 'size-3.5' };
export function buttonClassNames(size: ButtonSize, iconOnly = false, className?: string) {
  return cx(base, sizes[size], iconOnly && 'ui-button--icon-only !p-0', className);
}

export function Button({
  variant = 'primary',
  size = 'medium',
  iconOnly = false,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  children,
  className,
  type = 'button',
  isLoading = false,
  loadingLabel,
  disabled,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={isLoading && type === 'submit' ? 'button' : type}
      disabled={disabled}
      aria-disabled={isLoading || props['aria-disabled'] || undefined}
      aria-busy={isLoading || undefined}
      aria-description={isLoading && loadingLabel ? loadingLabel : props['aria-description']}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      data-loading={isLoading || undefined}
      data-loading-label={loadingLabel !== undefined || undefined}
      className={buttonClassNames(size, iconOnly, className)}
      onClick={event => { if (isLoading || props['aria-disabled'] === true || props['aria-disabled'] === 'true') { event.preventDefault(); event.stopPropagation(); return; } onClick?.(event); }}
      onKeyDown={event => { if (isLoading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); return; } onKeyDown?.(event); }}
    >
      {LeadingIcon && <span className="ui-button__leading-slot" aria-hidden><LeadingIcon className={cx(buttonIconClassNames[size], 'ui-button__leading-icon')}/></span>}
      {!iconOnly && <span className="ui-button__label">{children}</span>}
      {!iconOnly && TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
      <Spinner className="ui-button__busy-spinner" size={size === 'xs' ? 'xs' : size === 'small' ? 'sm' : 'md'}/>
    </button>
  );
}

'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

'use client';

import { useEffect, useState } from 'react';
import { Button as AriaButton, Calendar, Dialog, DialogTrigger, Popover } from 'react-aria-components';
import type { CalendarDate } from '@internationalized/date';
import { RiArrowDownSLine, RiCalendarLine } from '@remixicon/react';
import { Button } from '@/components/base/buttons/button';
import { cx } from '@/utils/cx';
import { useFieldDisabled } from '@/components/base/field/field-context';
import { DateChipInput, formatTriggerDate, MonthPanel } from './shared';

export interface DatePickerProps {
  value?: CalendarDate | null;
  defaultValue?: CalendarDate | null;
  onChange?: (value: CalendarDate | null) => void;
  isDisabled?: boolean;
  className?: string;
  placeholder?: string;
  'aria-label'?: string;
}

export function DatePicker({ value, defaultValue = null, onChange, isDisabled: disabled, className, placeholder = 'Select date', 'aria-label': ariaLabel = 'Date' }: DatePickerProps) {
  const isDisabled = useFieldDisabled(disabled);
  const [internalValue, setInternalValue] = useState<CalendarDate | null>(defaultValue);
  const committed = value === undefined ? internalValue : value;
  const [pending, setPending] = useState<CalendarDate | null>(committed);
  const [isOpen, setOpen] = useState(false);
  const [openKey, setOpenKey] = useState(0);
  useEffect(() => { if (isDisabled) setOpen(false); }, [isDisabled]);

  function openChange(next: boolean) {
    if (next) {
      setPending(committed);
      setOpenKey(key => key + 1);
    }
    setOpen(next);
  }

  function apply() {
    if (!pending) return;
    if (value === undefined) setInternalValue(pending);
    onChange?.(pending);
    setOpen(false);
  }

  return <DialogTrigger isOpen={isOpen} onOpenChange={openChange}>
    <AriaButton isDisabled={isDisabled} aria-label={ariaLabel} className={cx('ui-date-trigger', className)}>
      <RiCalendarLine size={18} aria-hidden />
      <span>{committed ? formatTriggerDate(committed) : placeholder}</span>
      <RiArrowDownSLine size={16} aria-hidden />
    </AriaButton>
    <Popover placement="bottom end" offset={8} className="ui-date-popover ui-date-popover--single">
      {({isExiting})=><Dialog inert={isExiting || Boolean(isDisabled)} aria-label={ariaLabel} className="ui-date-dialog">
        <Calendar key={openKey} aria-label={ariaLabel} value={pending} onChange={setPending} className="ui-single-calendar">
          <MonthPanel showPrev showNext />
          <div className="ui-date-footer"><div className="ui-date-footer__summary">{pending && <DateChipInput date={pending} label="Selected date" onCommit={setPending} />}</div><div className="ui-date-footer__actions"><Button variant="secondary" onClick={() => openChange(false)}>Cancel</Button><Button disabled={!pending} onClick={apply}>Apply</Button></div></div>
        </Calendar>
      </Dialog>}
    </Popover>
  </DialogTrigger>;
}

'use client';

import { useEffect, useState } from 'react';
import { Button as AriaButton, Dialog, DialogTrigger, Popover, RangeCalendar } from 'react-aria-components';
import { CalendarDate, endOfMonth, endOfYear, getLocalTimeZone, isSameDay, startOfMonth, startOfYear, today } from '@internationalized/date';
import { RiCalendarLine, RiArrowDownSLine } from '@remixicon/react';
import { Button } from '@/components/base/buttons/button';
import { cx } from '@/utils/cx';
import { useFieldDisabled } from '@/components/base/field/field-context';
import { DateChipInput, formatTriggerDate, MonthPanel } from './shared';

export interface DateRangeValue { start: CalendarDate; end: CalendarDate }
export interface DateRangePickerProps {
  value?: DateRangeValue | null;
  defaultValue?: DateRangeValue | null;
  onChange?: (value: DateRangeValue | null) => void;
  isDisabled?: boolean;
  className?: string;
  placeholder?: string;
  'aria-label'?: string;
}

function presets(): { label: string; range: DateRangeValue }[] {
  const now = today(getLocalTimeZone());
  const yesterday = now.subtract({ days: 1 });
  const lastMonth = now.subtract({ months: 1 });
  const lastYear = now.subtract({ years: 1 });
  return [
    { label: 'Today', range: { start: now, end: now } },
    { label: 'Yesterday', range: { start: yesterday, end: yesterday } },
    { label: 'Last week', range: { start: now.subtract({ days: 7 }), end: yesterday } },
    { label: 'This month', range: { start: startOfMonth(now), end: endOfMonth(now) } },
    { label: 'Last month', range: { start: startOfMonth(lastMonth), end: endOfMonth(lastMonth) } },
    { label: 'This year', range: { start: startOfYear(now), end: endOfYear(now) } },
    { label: 'Last year', range: { start: startOfYear(lastYear), end: endOfYear(lastYear) } },
    { label: 'All time', range: { start: now.subtract({ years: 10 }), end: now } },
  ];
}

function daysInRange(range: DateRangeValue) {
  const difference = Date.UTC(range.end.year, range.end.month - 1, range.end.day) - Date.UTC(range.start.year, range.start.month - 1, range.start.day);
  return Math.round(difference / 86_400_000) + 1;
}

export function DateRangePicker({ value, defaultValue = null, onChange, isDisabled: disabled, className, placeholder = 'Select date range', 'aria-label': ariaLabel = 'Date range' }: DateRangePickerProps) {
  const isDisabled = useFieldDisabled(disabled);
  const [internalValue, setInternalValue] = useState<DateRangeValue | null>(defaultValue);
  const committed = value === undefined ? internalValue : value;
  const [pending, setPending] = useState<DateRangeValue | null>(committed);
  const [isOpen, setOpen] = useState(false);
  const [openKey, setOpenKey] = useState(0);
  const [isCompact, setCompact] = useState(false);
  const choices = presets();
  useEffect(() => { if (isDisabled) setOpen(false); }, [isDisabled]);

  useEffect(() => {
    const query = window.matchMedia('(max-width: 880px)');
    const update = () => setCompact(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);

  function openChange(next: boolean) {
    if (next) {
      setPending(committed);
      setOpenKey(key => key + 1);
    }
    setOpen(next);
  }

  function apply() {
    if (!pending) return;
    if (value === undefined) setInternalValue(pending);
    onChange?.(pending);
    setOpen(false);
  }

  return <DialogTrigger isOpen={isOpen} onOpenChange={openChange}>
    <AriaButton isDisabled={isDisabled} aria-label={ariaLabel} className={cx('ui-date-trigger', className)}>
      <RiCalendarLine size={18} aria-hidden />
      <span>{committed ? `${formatTriggerDate(committed.start)} – ${formatTriggerDate(committed.end)}` : placeholder}</span>
      <RiArrowDownSLine size={16} aria-hidden />
    </AriaButton>
    <Popover placement="bottom end" offset={8} className="ui-date-popover">
      {({isExiting})=><Dialog inert={isExiting || Boolean(isDisabled)} aria-label={ariaLabel} className="ui-date-dialog">
        <RangeCalendar key={openKey} aria-label={ariaLabel} visibleDuration={{ months: isCompact ? 1 : 2 }} value={pending} onChange={setPending} className="ui-range-calendar">
          <div className="ui-date-range-layout">
            <div className="ui-date-presets" aria-label="Quick date ranges">
              {choices.map(({ label, range }) => <button key={label} type="button" aria-pressed={!!pending && isSameDay(pending.start, range.start) && isSameDay(pending.end, range.end)} onClick={() => setPending(range)}>{label}</button>)}
            </div>
            <div className="ui-date-range-main">
              <div className="ui-date-range-months"><MonthPanel showPrev showNext /><MonthPanel offset={1} showNext /></div>
              <div className="ui-date-footer">
                <div className="ui-date-footer__summary">
                  {pending && <><DateChipInput date={pending.start} label="Start date" onCommit={start => setPending({ start, end: start.compare(pending.end) > 0 ? start : pending.end })} /><span>–</span><DateChipInput date={pending.end} label="End date" onCommit={end => setPending({ start: end.compare(pending.start) < 0 ? end : pending.start, end })} /><span className="ui-date-day-count">{daysInRange(pending)} days selected</span></>}
                </div>
                <div className="ui-date-footer__actions"><Button variant="secondary" onClick={() => openChange(false)}>Cancel</Button><Button disabled={!pending} onClick={apply}>Apply</Button></div>
              </div>
            </div>
          </div>
        </RangeCalendar>
      </Dialog>}
    </Popover>
  </DialogTrigger>;
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import { Button as AriaButton, Calendar, Dialog, DialogTrigger, Popover } from 'react-aria-components';
import { CalendarDate, getLocalTimeZone, today } from '@internationalized/date';
import { RiArrowDownSLine, RiCalendarLine, RiGlobalLine, RiTimeLine, RiVideoOnLine } from '@remixicon/react';
import { cx } from '@/utils/cx';
import { useFieldDisabled } from '@/components/base/field/field-context';
import { MonthPanel } from './shared';
import { Select } from '@/components/base/select/select';

export interface MeetingSelection { date: CalendarDate; time: string; timezone: string }
export interface MeetingSchedulerProps {
  host?: { name: string; initials: string; role?: string };
  meeting?: { title: string; description?: string; durationMinutes: number; location?: string };
  value?: MeetingSelection | null;
  defaultValue?: MeetingSelection | null;
  onChange?: (value: MeetingSelection) => void;
  timezone?: string;
  timezones?: string[];
  startHour?: number;
  endHour?: number;
  slotMinutes?: number;
  className?: string;
  isDisabled?: boolean;
}

const defaultHost = { name: 'Maya Chen', initials: 'MC', role: 'Product designer' };
const defaultMeeting = { title: 'Introductory call', description: 'A short conversation about what you are building.', durationMinutes: 30, location: 'Video meeting' };

function timeLabel(time: string, is24Hour: boolean) {
  if (is24Hour) return time;
  const [hour, minute] = time.split(':').map(Number);
  return `${hour % 12 || 12}:${String(minute).padStart(2, '0')} ${hour >= 12 ? 'PM' : 'AM'}`;
}

export function MeetingScheduler({ host = defaultHost, meeting = defaultMeeting, value, defaultValue = null, onChange, timezone = Intl.DateTimeFormat().resolvedOptions().timeZone, timezones, startHour = 9, endHour = 18, slotMinutes = 30, className, isDisabled: disabled }: MeetingSchedulerProps) {
  const isDisabled = useFieldDisabled(disabled);
  const [internalValue, setInternalValue] = useState<MeetingSelection | null>(defaultValue);
  const committed = value === undefined ? internalValue : value;
  const [isOpen, setOpen] = useState(false);
  const [date, setDate] = useState<CalendarDate>(committed?.date ?? today(getLocalTimeZone()));
  const [selectedTime, setSelectedTime] = useState(committed?.time ?? '');
  const [selectedTimezone, setSelectedTimezone] = useState(committed?.timezone ?? timezone);
  const [is24Hour, set24Hour] = useState(true);
  const [openKey, setOpenKey] = useState(0);
  useEffect(() => { if (isDisabled) setOpen(false); }, [isDisabled]);
  const availableTimezones = timezones?.length ? timezones : Array.from(new Set([timezone, 'UTC', 'America/New_York', 'Europe/London', 'Europe/Istanbul']));
  const slots = useMemo(() => {
    const result: string[] = [];
    for (let minutes = startHour * 60; minutes < endHour * 60; minutes += slotMinutes) result.push(`${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`);
    return result;
  }, [startHour, endHour, slotMinutes]);

  function openChange(next: boolean) {
    if (next) {
      setDate(committed?.date ?? today(getLocalTimeZone()));
      setSelectedTime(committed?.time ?? '');
      setSelectedTimezone(committed?.timezone ?? timezone);
      setOpenKey(key => key + 1);
    }
    setOpen(next);
  }

  function chooseTime(time: string) {
    setSelectedTime(time);
    const next = { date, time, timezone: selectedTimezone };
    if (value === undefined) setInternalValue(next);
    onChange?.(next);
    setOpen(false);
  }

  return <DialogTrigger isOpen={isOpen} onOpenChange={openChange}>
    <AriaButton isDisabled={isDisabled} className={cx('ui-date-trigger', className)}><RiCalendarLine size={18} aria-hidden /><span>{committed ? `${committed.date.month}/${committed.date.day} · ${timeLabel(committed.time, is24Hour)}` : 'Schedule a meeting'}</span><RiArrowDownSLine size={16} aria-hidden /></AriaButton>
    <Popover placement="bottom start" offset={8} className="ui-date-popover ui-scheduler-popover">
      {({isExiting})=><Dialog inert={isExiting || Boolean(isDisabled)} aria-label="Schedule a meeting" className="ui-date-dialog">
        <div className="ui-scheduler">
          <div className="ui-scheduler__details">
            <span className="ui-scheduler__avatar" aria-hidden>{host.initials}</span>
            <span className="ui-scheduler__host">{host.name}</span>
            {host.role && <span className="ui-scheduler__role">{host.role}</span>}
            <h3>{meeting.title}</h3>
            {meeting.description && <p>{meeting.description}</p>}
            <span className="ui-scheduler__info"><RiTimeLine size={17} aria-hidden />{meeting.durationMinutes} minutes</span>
            <span className="ui-scheduler__info"><RiVideoOnLine size={17} aria-hidden />{meeting.location ?? 'Video meeting'}</span>
          </div>
          <Calendar key={openKey} aria-label="Meeting date" value={date} onChange={setDate} minValue={today(getLocalTimeZone())} className="ui-scheduler__calendar"><MonthPanel showPrev showNext /></Calendar>
          <div className="ui-scheduler__times">
            <strong>Available times</strong>
            <div className="ui-scheduler__timezone"><Select aria-label="Time zone" selectedKey={selectedTimezone} onSelectionChange={value=>{if(value)setSelectedTimezone(value);}} options={availableTimezones.map(item=>({id:item,label:item.replaceAll('_', ' '),leading:<RiGlobalLine size={16} aria-hidden/>}))}/></div>
            <div className="ui-scheduler__format" aria-label="Time format"><button type="button" aria-pressed={!is24Hour} onClick={() => set24Hour(false)}>12h</button><button type="button" aria-pressed={is24Hour} onClick={() => set24Hour(true)}>24h</button></div>
            <div className="ui-scheduler__slots" aria-label="Available time slots">{slots.map(time => <button key={time} type="button" aria-pressed={selectedTime === time} onClick={() => chooseTime(time)}>{timeLabel(time, is24Hour)}</button>)}</div>
          </div>
        </div>
      </Dialog>}
    </Popover>
  </DialogTrigger>;
}

'use client';

import { useContext, useEffect, useState } from 'react';
import { Button as AriaButton, CalendarCell, CalendarGrid, CalendarGridBody, CalendarGridHeader, CalendarHeaderCell, CalendarStateContext, RangeCalendarStateContext } from 'react-aria-components';
import type { CalendarCellRenderProps } from 'react-aria-components';
import { CalendarDate, getLocalTimeZone } from '@internationalized/date';
import { RiArrowLeftSLine, RiArrowRightSLine } from '@remixicon/react';

export function formatTriggerDate(date: CalendarDate) {
  return new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric' }).format(date.toDate(getLocalTimeZone()));
}

export function formatChipDate(date: CalendarDate) {
  return `${String(date.day).padStart(2, '0')}/${String(date.month).padStart(2, '0')}/${date.year}`;
}

export function parseChipDate(value: string) {
  const match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(value.trim());
  if (!match) return null;
  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = Number(match[3]);
  const test = new Date(Date.UTC(year, month - 1, day));
